-- Jornada: in place of the old karma screen, the user lives one labor of a myth each month,
-- through the seven stages of the hero's journey. The myths go in a fixed order: when one
-- ends, the next begins. Their texts are seeded here and stay editable.
CREATE TABLE IF NOT EXISTS "JourneyMyth" (
  id TEXT PRIMARY KEY NOT NULL,
  position INTEGER NOT NULL,         -- order in which the myths are lived
  hero TEXT NOT NULL,
  title TEXT NOT NULL,
  tradition TEXT,
  summary TEXT NOT NULL
);

-- One labor (or island, trial, book) of a myth: lived during one month.
CREATE TABLE IF NOT EXISTS "JourneyLabor" (
  id TEXT PRIMARY KEY NOT NULL,
  mythId TEXT NOT NULL,
  position INTEGER NOT NULL,         -- 1, 2, 3… inside the myth
  title TEXT NOT NULL,
  story TEXT NOT NULL,              -- the episode, in two or three sentences
  symbol TEXT NOT NULL,             -- what it traditionally stands for
  question TEXT NOT NULL            -- the reflection of the month
);
CREATE UNIQUE INDEX IF NOT EXISTS "JourneyLabor_myth_position_key" ON "JourneyLabor" (mythId, position);

-- A month lived with one labor. The stages follow the calendar; the texts are the user's own.
CREATE TABLE IF NOT EXISTS "JourneyCycle" (
  id TEXT PRIMARY KEY NOT NULL,
  userId TEXT NOT NULL,
  laborId TEXT NOT NULL,
  month TEXT NOT NULL,              -- YYYY-MM
  startDate TEXT NOT NULL,          -- YYYY-MM-DD; the first cycle may start mid-month
  monster TEXT,                     -- O chamado: where the monster shows up in the user's life
  master TEXT,                      -- O mestre: the teaching taken along
  abyss TEXT,                       -- O abismo: the fall of the month and the way back
  elixir TEXT,                      -- O elixir: what changed
  outcome TEXT,                     -- NULL (open) | CUMPRIDO | REPETIR (the labor is lived again)
  closedAt TEXT,
  createdAt TEXT NOT NULL,
  updatedAt TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "JourneyCycle_userId_month_key" ON "JourneyCycle" (userId, month);

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('hercules', 1, 'Hércules', 'Os doze trabalhos', 'Mitologia grega', 'Hércules, filho de Zeus, cumpre doze trabalhos para se purificar e alcançar a imortalidade. Cada trabalho só é vencido quando ele muda o modo de lutar.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-01', 'hercules', 1, 'O Leão de Nemeia', 'Um leão de pele invulnerável aterrorizava Nemeia. As flechas não o feriam: Hércules o encurralou na caverna e o venceu com as próprias mãos. Depois vestiu a sua pele.', 'A força do ego, que nenhuma arma de fora fere e só se doma de perto. Dominada, vira proteção.', 'Onde o meu orgulho reage antes de mim, e como seria enfrentá-lo de mãos nuas?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-02', 'hercules', 2, 'A Hidra de Lerna', 'Para cada cabeça cortada nasciam duas. Hércules só a venceu quando Iolau queimou cada ferida, e enterrou sob uma pedra a cabeça que não morria.', 'Desejos e hábitos que se multiplicam quando são só cortados. Pedem o fogo da consciência e a ajuda de um companheiro.', 'Que desejo volta mais forte toda vez que eu só o reprimo?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-03', 'hercules', 3, 'A Corça de Cerineia', 'A corça de chifres de ouro, consagrada a Ártemis, corria sem cansar. Hércules a perseguiu por um ano inteiro para capturá-la sem feri-la.', 'A paciência com o ideal: o sagrado não se agarra à força nem se apressa.', 'Que ideal eu persigo com pressa, e como seria persegui-lo sem ferir?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-04', 'hercules', 4, 'O Javali de Erimanto', 'Um javali feroz devastava o monte Erimanto. Hércules o cansou na neve funda e o trouxe vivo nos ombros.', 'O instinto bruto, que precisa ser conduzido e não destruído.', 'Que impulso me arrasta, e como posso conduzi-lo em vez de só lutar contra ele?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-05', 'hercules', 5, 'Os Estábulos de Áugias', 'Os estábulos do rei Áugias acumulavam anos de sujeira. Hércules os limpou num só dia, desviando o curso de dois rios.', 'A purificação do que foi acumulado. Pede inteligência, não só esforço.', 'O que acumulei por anos que pede uma limpeza, e qual é o rio que pode fazê-la?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-06', 'hercules', 6, 'As Aves do Estínfalo', 'Aves de penas de bronze infestavam o lago Estínfalo, escondidas no mato. Hércules as espantou com chocalhos de bronze e as abateu quando levantaram voo.', 'A mente ruidosa e dispersa, os pensamentos que ferem. Vencem-se quando são trazidos à luz.', 'Que pensamentos repetidos fazem barulho em mim, e o que os faz levantar voo?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-07', 'hercules', 7, 'O Touro de Creta', 'Um touro enviado por Poseidon enlouqueceu e devastava Creta. Hércules o dominou e o levou pelo mar até a Grécia.', 'A força passional, que pode ser montada e conduzida.', 'Onde a minha força vira fúria, e para onde eu poderia conduzi-la?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-08', 'hercules', 8, 'As Éguas de Diomedes', 'O rei Diomedes alimentava as suas éguas com carne humana. Hércules as dominou, mas o companheiro a quem as confiou foi devorado.', 'As paixões que devoram, e o perigo de entregar a outro um trabalho que é seu.', 'Que trabalho interior eu delego, quando ele é só meu?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-09', 'hercules', 9, 'O Cinturão de Hipólita', 'Hércules foi buscar o cinturão da rainha das amazonas. Ela o daria de boa vontade, mas um boato provocou a luta e a perda.', 'O que se conquista sem violência, e o mal-entendido que destrói.', 'Onde eu desconfio e ataco quando poderia simplesmente receber?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-10', 'hercules', 10, 'Os Bois de Gerião', 'No extremo ocidente, o gigante Gerião, de três corpos, guardava bois vermelhos. Hércules o venceu e trouxe o rebanho numa longa viagem.', 'Unir corpo, emoção e mente numa só direção.', 'O meu corpo, as minhas emoções e a minha mente querem a mesma coisa?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-11', 'hercules', 11, 'Os Pomos das Hespérides', 'Para obter os pomos de ouro, Hércules sustentou o céu no lugar de Atlas enquanto ele os colhia, e depois precisou de astúcia para devolver o peso.', 'A sabedoria que se alcança servindo e carregando o peso que cabe a cada um.', 'Que peso do mundo me cabe carregar, e qual não é meu?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('hercules-12', 'hercules', 12, 'Cérbero', 'O último trabalho foi descer ao Hades e trazer Cérbero, o cão de três cabeças. Hércules o dominou sem armas e depois o devolveu ao seu lugar.', 'A descida aos infernos e o medo da morte vencido pelo domínio de si.', 'Qual é o medo mais fundo que eu evito olhar?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('ulisses', 2, 'Ulisses', 'A Odisseia', 'Homero · mitologia grega', 'Depois de Troia, Ulisses leva dez anos para voltar a Ítaca. Cada ilha é uma tentação ou um perigo que testa a lembrança de quem ele é e para onde vai.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-01', 'ulisses', 1, 'Os Cícones', 'Os gregos saqueiam a cidade dos cícones e, por se demorarem no banquete, são atacados e perdem muitos homens.', 'A vitória que se perde por não saber parar.', 'Onde eu me demoro depois de vencer?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-02', 'ulisses', 2, 'Os Lotófagos', 'Os companheiros que comem a flor de lótus esquecem o caminho de casa, e Ulisses os leva à força de volta ao navio.', 'O esquecimento: o prazer que faz perder o propósito.', 'O que me faz esquecer do meu caminho?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-03', 'ulisses', 3, 'O Ciclope', 'Preso na caverna de Polifemo, Ulisses diz que se chama Ninguém e o vence com astúcia. Na fuga, por vaidade, grita o próprio nome.', 'A força bruta vencida pela inteligência, e a vaidade que cobra o seu preço.', 'Quando a vaidade estraga o que a inteligência conquistou?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-04', 'ulisses', 4, 'O odre dos ventos', 'Éolo lhe dá os ventos contrários presos num odre. Já à vista de Ítaca, os companheiros o abrem por cobiça, e a tempestade os leva de volta.', 'A desconfiança e a cobiça que desfazem um caminho quase cumprido.', 'O que eu ponho a perder quando estou perto da meta?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-05', 'ulisses', 5, 'Os Lestrigões', 'Gigantes devoradores destroem quase toda a frota. Só o navio de Ulisses escapa.', 'A perda que não se pode evitar, e seguir adiante com o que restou.', 'O que perdi e ainda não aceitei?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-06', 'ulisses', 6, 'Circe', 'A feiticeira transforma os companheiros em porcos. Com a erva que Hermes lhe dá, Ulisses resiste ao encanto e os liberta.', 'O encanto que rebaixa o humano ao animal, e o discernimento que protege.', 'Que encanto me rebaixa, e qual é a minha erva de Hermes?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-07', 'ulisses', 7, 'A descida ao Hades', 'Ulisses desce ao reino dos mortos para ouvir o adivinho Tirésias e reencontra a própria mãe.', 'Encarar a morte e os que partiram para receber orientação.', 'Que conselho dos que vieram antes de mim eu preciso ouvir?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-08', 'ulisses', 8, 'As Sereias', 'Amarrado ao mastro, Ulisses ouve o canto das sereias enquanto os companheiros remam com cera nos ouvidos.', 'Conhecer a tentação sem se entregar a ela, com compromissos firmados antes.', 'A que mastro preciso me amarrar antes que o canto comece?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-09', 'ulisses', 9, 'Cila e Caríbdis', 'Entre o monstro de seis cabeças e o redemoinho que engole navios, Ulisses escolhe passar perto do mal menor.', 'A escolha difícil entre duas perdas.', 'Que escolha eu adio porque nenhuma opção é sem custo?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-10', 'ulisses', 10, 'Os bois do Sol', 'Famintos, os companheiros comem o gado sagrado de Hélio enquanto Ulisses dorme, e o navio é destruído por um raio.', 'A impaciência que profana o sagrado.', 'Onde a minha fome me faz tocar o que é sagrado?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-11', 'ulisses', 11, 'Calipso', 'A ninfa o retém por sete anos e lhe oferece a imortalidade. Ulisses chora na praia, olhando o mar, porque quer voltar.', 'O conforto que aprisiona, e a escolha da própria condição humana.', 'Que conforto me prende longe de onde eu deveria estar?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('ulisses-12', 'ulisses', 12, 'O retorno a Ítaca', 'Disfarçado de mendigo, Ulisses volta, é reconhecido pelo velho cão Argos e retoma a sua casa.', 'Voltar a si mesmo com humildade e pôr ordem na própria casa.', 'O que precisa ser posto em ordem na minha casa interior?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('teseu', 3, 'Teseu', 'O caminho de Atenas e o labirinto', 'Mitologia grega', 'Teseu vai por terra até Atenas vencendo os bandidos do caminho e depois entra no labirinto de Creta para vencer o Minotauro.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-01', 'teseu', 1, 'A espada sob a pedra', 'Já crescido, Teseu ergue a grande pedra sob a qual o pai deixou uma espada e um par de sandálias.', 'Descobrir a própria origem e a força herdada.', 'Que força herdei e ainda não ergui?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-02', 'teseu', 2, 'Perifetes', 'O bandido matava os viajantes com uma maça de bronze. Teseu o vence e passa a usar a sua maça.', 'Tomar a arma do adversário e transformá-la em instrumento.', 'Que dificuldade minha pode virar ferramenta?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-03', 'teseu', 3, 'Sínis', 'Sínis amarrava os viajantes a pinheiros curvados e os soltava. Teseu o vence pelo mesmo método.', 'O mal que se volta contra quem o pratica.', 'Que dano eu causo que acaba voltando para mim?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-04', 'teseu', 4, 'Círon', 'Círon obrigava os viajantes a lavar os seus pés e os chutava do penhasco. Teseu o lança ao mar.', 'A humilhação, e não se curvar ao que rebaixa.', 'Diante de quem ou de quê eu me curvo sem dever?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-05', 'teseu', 5, 'Procusto', 'Procusto esticava ou cortava os hóspedes para caberem na sua cama. Teseu lhe dá a mesma medida.', 'A rigidez que quer moldar tudo à própria medida.', 'Que medida rígida eu imponho a mim ou aos outros?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-06', 'teseu', 6, 'O Minotauro', 'Com o fio de Ariadne, Teseu entra no labirinto, vence o Minotauro e reencontra a saída.', 'Entrar no centro de si, onde vive o monstro, guiado por um fio de consciência.', 'Qual é o meu fio para não me perder dentro de mim?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('teseu-07', 'teseu', 7, 'As velas negras', 'Na volta, Teseu esquece de trocar as velas negras pelas brancas, e o pai, pensando-o morto, se lança ao mar.', 'O esquecimento na vitória, e a responsabilidade com quem espera por nós.', 'O que eu esqueço de fazer pelos que me esperam?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('rama', 4, 'Rama', 'O Ramayana', 'Valmiki · Índia', 'Rama, príncipe de Ayodhya, aceita o exílio para cumprir a palavra do pai, perde Sita para o demônio Ravana e a resgata com a ajuda de Hanuman. É o herói do dharma, o dever justo. As sete etapas seguem os sete livros do poema.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-01', 'rama', 1, 'O arco de Shiva', 'Educado pelos sábios, Rama conquista Sita ao vergar o grande arco de Shiva, que ninguém conseguia sequer erguer.', 'A formação: a força que nasce da disciplina e da pureza.', 'Que disciplina está me formando agora?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-02', 'rama', 2, 'O exílio', 'Na véspera de ser coroado, Rama aceita catorze anos de exílio na floresta para que o pai cumpra uma promessa.', 'O dharma: cumprir o dever sem ressentimento, mesmo quando custa tudo.', 'Que dever eu cumpro com ressentimento?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-03', 'rama', 3, 'O cervo dourado', 'Na floresta, um cervo dourado afasta Rama e o irmão Lakshmana, e Ravana rapta Sita.', 'A ilusão dourada que nos tira de perto do que é mais precioso.', 'Que cervo dourado me afasta do essencial?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-04', 'rama', 4, 'A aliança', 'Rama se alia ao rei dos macacos, Sugriva, e conhece Hanuman.', 'Os aliados inesperados e a humildade de pedir ajuda.', 'De quem eu poderia aceitar ajuda?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-05', 'rama', 5, 'O salto de Hanuman', 'Hanuman salta o oceano até Lanka, encontra Sita e lhe entrega o anel de Rama.', 'A devoção que faz o impossível.', 'O que eu faria se confiasse plenamente?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-06', 'rama', 6, 'Ravana', 'Sobre uma ponte de pedras o exército atravessa o mar, e Rama vence Ravana, o demônio de dez cabeças.', 'A luta contra o ego de muitas cabeças.', 'Qual das cabeças de Ravana está mais viva em mim?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('rama-07', 'rama', 7, 'O retorno a Ayodhya', 'Rama volta, é coroado, e o seu reino fica conhecido como o tempo da justiça.', 'Voltar e governar a própria vida com retidão.', 'Como seria governar o meu dia com justiça?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('psique', 5, 'Psiquê', 'Eros e Psiquê', 'Apuleio · mitologia greco-romana', 'Psiquê, cujo nome quer dizer alma, perde Eros por desconfiar dele. Para reencontrá-lo, cumpre as quatro tarefas impostas por Afrodite.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('psique-01', 'psique', 1, 'Os grãos misturados', 'Afrodite manda Psiquê separar uma montanha de grãos misturados numa só noite. As formigas a ajudam.', 'Pôr ordem no caos interior, grão por grão, aceitando pequenas ajudas.', 'Que confusão em mim pede ser separada com paciência?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('psique-02', 'psique', 2, 'A lã de ouro', 'Ela deve trazer a lã dos carneiros de ouro, que matam quem se aproxima. Um junco lhe ensina a esperar o entardecer e a colher a lã presa nos arbustos.', 'Não enfrentar a força no seu auge: esperar e colher de modo indireto.', 'Onde eu forço quando deveria esperar?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('psique-03', 'psique', 3, 'A água do Estige', 'Ela deve encher um jarro na fonte do Estige, guardada por dragões. A águia de Zeus voa e o enche por ela.', 'Ver o todo do alto e tomar só a medida necessária.', 'Do que eu preciso tomar só a medida certa?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('psique-04', 'psique', 4, 'A caixa de Perséfone', 'Ela desce ao Hades para buscar a beleza de Perséfone e não deve abrir a caixa. Abre, cai num sono de morte, e Eros a desperta.', 'A descida, a curiosidade que quase destrói, e o amor que desperta a alma.', 'O que em mim só o amor pode despertar?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('perseu', 6, 'Perseu', 'Perseu e a Medusa', 'Mitologia grega', 'Para salvar a mãe, Perseu promete trazer a cabeça da Medusa, cujo olhar transforma em pedra. Ele vence com os dons dos deuses e com o reflexo.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-01', 'perseu', 1, 'A promessa', 'Para proteger a mãe do rei Polidectes, Perseu promete trazer-lhe a cabeça da Medusa.', 'O chamado que nasce de um compromisso assumido.', 'Que compromisso já assumi e ainda não honrei?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-02', 'perseu', 2, 'Os dons dos deuses', 'Atena lhe dá um escudo polido como espelho, e Hermes, sandálias aladas e uma foice.', 'Receber a ajuda do alto antes de enfrentar o que petrifica.', 'Que instrumentos já me foram dados para esta luta?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-03', 'perseu', 3, 'As Greias', 'As três velhas irmãs têm um só olho, que passam de mão em mão. Perseu o toma para que lhe revelem o caminho.', 'Ver o que está oculto e perguntar a quem sabe.', 'O que eu não estou vendo, e a quem posso perguntar?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-04', 'perseu', 4, 'A Medusa', 'Quem olhava a Medusa virava pedra. Perseu a vence olhando apenas o seu reflexo no escudo.', 'O que paralisa não se encara de frente: vê-se refletido, com a calma do escudo de Atena.', 'O que me paralisa, e onde posso vê-lo refletido?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-05', 'perseu', 5, 'Andrômeda', 'Na volta, Perseu liberta Andrômeda, acorrentada a uma rocha diante de um monstro marinho.', 'Pôr a força conquistada a serviço de quem está preso.', 'A quem posso servir com o que conquistei?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('perseu-06', 'perseu', 6, 'A devolução dos dons', 'Perseu devolve os dons aos deuses e entrega a cabeça da Medusa a Atena, que a põe no seu escudo.', 'Devolver o poder ao seu lugar, sem se apropriar dele.', 'Que poder recebido eu preciso devolver?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('arjuna', 7, 'Arjuna', 'O Bhagavad Gita', 'Mahabharata · Índia', 'No campo de Kurukshetra, diante da batalha, o guerreiro Arjuna larga o arco. Krishna, o seu cocheiro, o ensina até que ele volte a agir com clareza.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-01', 'arjuna', 1, 'O desânimo de Arjuna', 'Entre os dois exércitos, Arjuna vê parentes e mestres do outro lado, larga o arco e se recusa a lutar.', 'A crise diante do dever, quando o apego paralisa a ação.', 'Diante de que batalha eu largo o arco?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-02', 'arjuna', 2, 'Krishna, o cocheiro', 'Krishna, que conduz o seu carro, começa a ensiná-lo ali mesmo, no meio do campo.', 'O mestre que fala quando o discípulo se rende e pergunta.', 'Que pergunta verdadeira eu faria ao meu mestre agora?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-03', 'arjuna', 3, 'O que não morre', 'Krishna ensina que o Ser não nasce nem morre: só os corpos passam, como roupas trocadas.', 'A distinção entre o eterno e o passageiro.', 'O que em mim não passa?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-04', 'arjuna', 4, 'A ação sem apego', 'Krishna ensina a cumprir o dever sem ser movido pelos frutos da ação.', 'Agir por dever, livre da ansiedade pelo resultado.', 'Que ação eu faço só pelo resultado?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-05', 'arjuna', 5, 'A mente inquieta', 'Arjuna diz que a mente é inquieta como o vento. Krishna responde que ela se aquieta com prática e desapego.', 'A mente domada pela prática constante.', 'Que prática está aquietando a minha mente?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-06', 'arjuna', 6, 'A forma universal', 'Krishna mostra a Arjuna a sua forma cósmica, e Arjuna, assombrado, vê a grandeza do todo.', 'A visão do todo que põe o pequeno eu no seu lugar.', 'Diante do todo, o que no meu problema é pequeno?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('arjuna-07', 'arjuna', 7, 'A decisão', 'Arjuna diz que a sua ilusão se desfez, retoma o arco e se levanta para cumprir o seu dever.', 'Voltar à ação com clareza, sem dúvida nem medo.', 'O que farei agora que vejo com clareza?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('gilgamesh', 8, 'Gilgamesh', 'A epopeia de Gilgamesh', 'Mesopotâmia', 'Gilgamesh, rei de Uruk, ganha um amigo, vence monstros, perde o amigo para a morte e parte em busca da imortalidade. Volta sabendo o que fica.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-01', 'gilgamesh', 1, 'O rei sem medida', 'Gilgamesh é tão forte que oprime o próprio povo. Os deuses criam Enkidu para equilibrá-lo.', 'A força sem medida, que pede um contrapeso.', 'Onde a minha força pesa sobre quem está perto?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-02', 'gilgamesh', 2, 'Enkidu, o amigo', 'Os dois lutam de igual para igual, e da luta nasce uma amizade profunda.', 'O outro que nos completa e nos humaniza.', 'Quem me equilibra, e eu o escuto?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-03', 'gilgamesh', 3, 'A floresta de cedros', 'Juntos, entram na floresta de cedros e vencem Humbaba, o seu guardião.', 'A coragem de entrar no desconhecido, e a pergunta sobre o que se destrói ao vencer.', 'Que conquista minha destruiu algo que não precisava?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-04', 'gilgamesh', 4, 'O Touro do Céu', 'Gilgamesh despreza a deusa Ishtar, que envia o Touro do Céu. Eles o matam, e os deuses condenam Enkidu.', 'A arrogância diante do sagrado e o seu preço.', 'Onde eu desafio o que deveria reverenciar?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-05', 'gilgamesh', 5, 'A morte do amigo', 'Enkidu adoece e morre. Gilgamesh chora por sete dias e descobre que também vai morrer.', 'O encontro com a morte, que muda o sentido da vida.', 'O que muda no meu dia se eu lembrar que vou morrer?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-06', 'gilgamesh', 6, 'A planta da juventude', 'Ele atravessa as águas da morte até Utnapishtim, o sobrevivente do dilúvio, encontra a planta da juventude e a perde para uma serpente.', 'A busca de escapar da condição humana, e a perda que ensina.', 'O que eu tento conservar a qualquer custo?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('gilgamesh-07', 'gilgamesh', 7, 'Os muros de Uruk', 'Gilgamesh volta e contempla os muros da cidade que construiu: a obra que fica depois do homem.', 'Aceitar a finitude e servir por meio da obra.', 'Que obra minha vai ficar?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('jasao', 9, 'Jasão', 'Os Argonautas e o Velo de Ouro', 'Mitologia grega', 'Jasão reúne os maiores heróis da Grécia na nau Argo e atravessa mares perigosos até a Cólquida para conquistar o Velo de Ouro.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-01', 'jasao', 1, 'A sandália perdida', 'Jasão chega à corte do rei Pélias com uma sandália só, perdida ao atravessar um rio, como dizia a profecia. O rei o envia em busca do Velo de Ouro.', 'O chamado que chega com uma marca: algo ficou para trás ao atravessar o rio.', 'O que deixei para trás ao aceitar este caminho?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-02', 'jasao', 2, 'A nau Argo', 'Jasão reúne os heróis num navio construído com a ajuda de Atena.', 'Ninguém atravessa sozinho: a escolha dos companheiros.', 'Quem são os meus companheiros de travessia?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-03', 'jasao', 3, 'Lemnos', 'Na ilha de Lemnos, os argonautas se demoram e esquecem por um tempo a viagem.', 'O repouso que vira esquecimento.', 'Onde o meu descanso virou desvio?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-04', 'jasao', 4, 'Fineu e as Harpias', 'Os argonautas libertam o adivinho Fineu das Harpias, e ele lhes ensina a passar pelas rochas que se chocam.', 'Servir primeiro e depois receber orientação.', 'Que serviço abre o meu caminho?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-05', 'jasao', 5, 'As rochas que se chocam', 'Soltam uma pomba entre as rochas e, quando elas se abrem, remam com toda a força para passar.', 'O momento exato: esperar o sinal e agir sem hesitar.', 'Que passagem estreita pede de mim decisão agora?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-06', 'jasao', 6, 'Os touros de fogo e o dragão', 'Na Cólquida, Jasão ara um campo com touros que soltam fogo e, com a ajuda de Medeia, adormece o dragão que guarda o Velo.', 'Domar a força ardente e adormecer o guardião do tesouro.', 'Que guardião em mim impede o acesso ao que é precioso?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('jasao-07', 'jasao', 7, 'O retorno com o Velo', 'Jasão volta com o Velo de Ouro, mas o modo como o conquistou cobra o seu preço pelo caminho.', 'O tesouro conquistado e as consequências de como foi conquistado.', 'Como eu conquisto o que quero, e o que isso me custa?');

INSERT OR IGNORE INTO "JourneyMyth" (id, position, hero, title, tradition, summary) VALUES ('parsifal', 10, 'Parsifal', 'A busca do Graal', 'Lenda arturiana', 'Parsifal, criado longe do mundo, chega ao castelo do Graal e não faz a pergunta que curaria o rei. Anos depois, transformado, volta e a faz.');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-01', 'parsifal', 1, 'O tolo da floresta', 'Criado pela mãe longe do mundo, Parsifal vê cavaleiros passarem e parte para ser um deles, ingênuo e desajeitado.', 'A pureza ingênua que ainda não conhece a si mesma.', 'Em que eu ainda sou ingênuo sobre mim?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-02', 'parsifal', 2, 'O mestre Gurnemanz', 'Um velho cavaleiro lhe ensina as armas e as maneiras, e o aconselha a não fazer perguntas demais.', 'O ensinamento recebido, que precisa ser compreendido e não só obedecido.', 'Que regra eu sigo sem entender?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-03', 'parsifal', 3, 'O castelo do Graal', 'No castelo do Rei Pescador, que sofre de uma ferida, Parsifal vê o Graal passar e se cala.', 'A pergunta não feita, a compaixão que não se manifestou.', 'Que pergunta de compaixão eu deixei de fazer?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-04', 'parsifal', 4, 'O castelo vazio', 'Ao acordar, o castelo está vazio e desaparece. Parsifal é censurado por não ter perguntado.', 'A queda que revela a falta.', 'O que perdi por omissão?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-05', 'parsifal', 5, 'Os anos de errância', 'Parsifal vaga por anos, revoltado contra Deus, vencendo combates que não levam a nada.', 'A noite escura, quando a força já não serve.', 'Contra o que eu luto sem sentido?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-06', 'parsifal', 6, 'O eremita', 'Numa Sexta-Feira Santa, um eremita o recebe, e Parsifal se arrepende e se reconcilia.', 'A humildade e o arrependimento que reabrem o caminho.', 'De que preciso me arrepender para seguir?');
INSERT OR IGNORE INTO "JourneyLabor" (id, mythId, position, title, story, symbol, question) VALUES ('parsifal-07', 'parsifal', 7, 'A pergunta que cura', 'Parsifal volta ao castelo e pergunta ao rei o que o aflige. O rei se cura, e Parsifal se torna o guardião do Graal.', 'A compaixão que cura, e o serviço como coroa da jornada.', 'Que dor ao meu redor pede a minha pergunta?');
